    "source": "def get_version():
    """Get the version and release from the source code."""

    file_path = src_directory / "cachetools/__init__.py"
    text_content = file_path.read_text()
    lines_list = text_content.splitlines()
    for current_line in lines_list:
        stripped_line = current_line.strip()
        if not stripped_line.startswith("__version__"):
            continue
        parts = stripped_line.partition("=")
        raw_value = parts[2].strip()
        clean_full_version = raw_value.strip("\"'")
        version_parts = clean_full_version.split(".")
        selected_parts = version_parts[:2]
        partial_result = ".".join(selected_parts)
        return clean_full_version, partial_result"
