    "source": "def __setitem__(self, key, value, cache_setitem=Cache.__setitem__):
    with self.timer as current_time:
        self.expire(current_time)
        cache_setitem(self, key, value)
    try:
        existing_link = self.__getlink(key)
    except KeyError:
        new_link = TTLCache._Link(key)
        self.__links[key] = new_link
        link = new_link
    else:
        existing_link.unlink()
        link = existing_link
    link.expires = current_time + self.__ttl
    root_node = self.__root
    link.next = root_node
    prev_node = root_node.prev
    link.prev = prev_node
    prev_node.next = link
    root_node.prev = link"
