    "source": "def __setstate__(self, state):
    self.__dict__.update(state)
    root_node = self.__root
    root_node.prev = root_node
    root_node.next = root_node
    sorted_links = sorted(self.__links.values(), key=lambda obj: obj.expires)
    for current_link in sorted_links:
        current_link.next = root_node
        prev_node = root_node.prev
        current_link.prev = prev_node
        prev_node.next = current_link
        root_node.prev = current_link
    self.expire(self.timer())"
