    "source": "def expire(self, time=None):
    """Remove expired items from the cache and return an iterable of the
    expired `(key, value)` pairs.

    """
    if time is None:
        time = self.timer()
    root_node = self.__root
    current_node = root_node.next
    links_dict = self.__links
    expired_list = []
    del_item_func = Cache.__delitem__
    get_item_func = Cache.__getitem__
    while current_node is not root_node and not (time < current_node.expires):
        item_key = current_node.key
        item_value = get_item_func(self, item_key)
        expired_list.append((item_key, item_value))
        del_item_func(self, item_key)
        del links_dict[item_key]
        next_node = current_node.next
        current_node.unlink()
        current_node = next_node
    return expired_list"
