    "source": "def __setitem__(self, key, value, cache_setitem=Cache.__setitem__):
    with self.timer as current_time:
        expires_at = self.__ttu(key, value, current_time)
        if not (current_time < expires_at):
            return
        self.expire(current_time)
        cache_setitem(self, key, value)
    try:
        existing_item = self.__getitem(key)
        existing_item.removed = True
    except KeyError:
        pass
    new_item = TLRUCache._Item(key, expires_at)
    self.__items[key] = new_item
    heapq.heappush(self.__order, new_item)"
