    "source": "def expire(self, time=None):
    """Remove expired items from the cache and return an iterable of the
    expired `(key, value)` pairs.

    """
    if time is None:
        time = self.timer()
    items_dict = self.__items
    order_heap = self.__order
    if len(order_heap) > len(items_dict) * 2:
        filtered_items = [item for item in order_heap if not item.removed]
        self.__order = filtered_items
        order_heap = filtered_items
        heapq.heapify(order_heap)
    expired_list = []
    del_item_func = Cache.__delitem__
    get_item_func = Cache.__getitem__
    while order_heap:
        top_item = order_heap[0]
        if top_item.removed or not (time < top_item.expires):
            heapq.heappop(order_heap)
            if not top_item.removed:
                item_key = top_item.key
                item_value = get_item_func(self, item_key)
                expired_list.append((item_key, item_value))
                del_item_func(self, item_key)
                del items_dict[item_key]
        else:
            break
    return expired_list"
