    "source": "def cached(cache, key=keys.hashkey, lock=None, info=False):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(func):
        if info:
            hits_count = 0
            misses_count = 0

            if isinstance(cache, Cache):

                def getinfo():
                    nonlocal hits_count, misses_count
                    return _CacheInfo(hits_count, misses_count, cache.maxsize, cache.currsize)

            elif isinstance(cache, collections.abc.Mapping):

                def getinfo():
                    nonlocal hits_count, misses_count
                    return _CacheInfo(hits_count, misses_count, None, len(cache))

            else:

                def getinfo():
                    nonlocal hits_count, misses_count
                    return _CacheInfo(hits_count, misses_count, 0, 0)

            if cache is None:

                def wrapper(*args, **kwargs):
                    nonlocal misses_count
                    misses_count += 1
                    return func(*args, **kwargs)

                def cache_clear():
                    nonlocal hits_count, misses_count
                    hits_count = 0
                    misses_count = 0

                cache_info_func = getinfo

            elif lock is None:

                def wrapper(*args, **kwargs):
                    nonlocal hits_count, misses_count
                    k = key(*args, **kwargs)
                    try:
                        result = cache[k]
                        hits_count += 1
                        return result
                    except KeyError:
                        misses_count += 1
                    v = func(*args, **kwargs)
                    try:
                        cache[k] = v
                    except ValueError:
                        pass
                    return v

                def cache_clear():
                    nonlocal hits_count, misses_count
                    cache.clear()
                    hits_count = 0
                    misses_count = 0

                cache_info_func = getinfo

            else:

                def wrapper(*args, **kwargs):
                    nonlocal hits_count, misses_count
                    k = key(*args, **kwargs)
                    try:
                        with lock:
                            result = cache[k]
                            hits_count += 1
                            return result
                    except KeyError:
                        with lock:
                            misses_count += 1
                    v = func(*args, **kwargs)
                    try:
                        with lock:
                            return cache.setdefault(k, v)
                    except ValueError:
                        return v

                def cache_clear():
                    nonlocal hits_count, misses_count
                    with lock:
                        cache.clear()
                        hits_count = 0
                        misses_count = 0

                def cache_info():
                    with lock:
                        return getinfo()

        else:
            if cache is None:

                def wrapper(*args, **kwargs):
                    return func(*args, **kwargs)

                def cache_clear():
                    pass

            elif lock is None:

                def wrapper(*args, **kwargs):
                    k = key(*args, **kwargs)
                    try:
                        return cache[k]
                    except KeyError:
                        pass
                    v = func(*args, **kwargs)
                    try:
                        cache[k] = v
                    except ValueError:
                        pass
                    return v

                def cache_clear():
                    cache.clear()

            else:

                def wrapper(*args, **kwargs):
                    k = key(*args, **kwargs)
                    try:
                        with lock:
                            return cache[k]
                    except KeyError:
                        pass
                    v = func(*args, **kwargs)
                    try:
                        with lock:
                            return cache.setdefault(k, v)
                    except ValueError:
                        return v

                def cache_clear():
                    with lock:
                        cache.clear()

            cache_info_func = None

        wrapper.cache = cache
        wrapper.cache_key = key
        wrapper.cache_lock = lock
        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info_func

        return functools.update_wrapper(wrapper, func)

    return decorator"
